() => {
  const links = document.querySelectorAll('a[aria-label]');
  const result = [];
  links.forEach((link, i) => {
    const label = link.getAttribute('aria-label');
    if (label && (label.includes('Park') || label.includes('parking') || label.includes('Parking') || label.includes('Washington') || label.includes('Public'))) {
      const rect = link.getBoundingClientRect();
      result.push({label, top: rect.top, left: rect.left, visible: rect.width > 0 && rect.height > 0});
    }
  });
  return result;
}

() => {
  const links = document.querySelectorAll('a[aria-label="Park Rite Parking"]');
  if (links.length > 0) {
    links[0].click();
    return {clicked: true, count: links.length};
  }
  return {clicked: false};
}

() => {
  const link = document.querySelector('a[aria-label="Park Rite Parking"]');
  if (link) {
    link.click();
    return {clicked: true, href: link.href};
  }
  return {clicked: false};
}

() => {
  document.dispatchEvent(new KeyboardEvent('keydown', {key: 'Escape'}));
  // Try also clicking any visible close button
  const closeButtons = document.querySelectorAll('button[aria-label*="关闭"], button[aria-label*="close"], button[aria-label*="Close"]');
  let result = [];
  closeButtons.forEach(b => result.push({label: b.getAttribute('aria-label'), visible: b.offsetParent !== null}));
  return result;
}

() => {
  // Try to find the modal overlay
  const modals = document.querySelectorAll('[role="dialog"], [role="alertdialog"], .modal, [aria-modal="true"]');
  let result = {modals: [], closeButtons: []};
  modals.forEach(m => {
    result.modals.push({
      tag: m.tagName,
      role: m.getAttribute('role'),
      ariaModal: m.getAttribute('aria-modal'),
      visible: m.offsetParent !== null
    });
  });

  // Find close buttons
  const closeButtons = document.querySelectorAll('button[aria-label*="关闭"], button[aria-label*="close"]');
  closeButtons.forEach(b => {
    const rect = b.getBoundingClientRect();
    result.closeButtons.push({
      label: b.getAttribute('aria-label'),
      top: rect.top,
      left: rect.left,
      visible: rect.width > 0 && rect.height > 0
    });
  });

  return result;
}

() => {
  // Try pressing escape
  const events = ['keydown', 'keyup', 'keypress'];
  events.forEach(type => {
    document.dispatchEvent(new KeyboardEvent(type, {key: 'Escape', code: 'Escape', keyCode: 27, which: 27, bubbles: true}));
    document.body.dispatchEvent(new KeyboardEvent(type, {key: 'Escape', code: 'Escape', keyCode: 27, which: 27, bubbles: true}));
  });

  // Look for any element with high z-index
  const allEls = document.querySelectorAll('*');
  let overlay = null;
  let maxZ = 0;
  allEls.forEach(el => {
    const z = parseInt(window.getComputedStyle(el).zIndex);
    if (z > maxZ && el.offsetParent !== null) {
      maxZ = z;
      overlay = {tag: el.tagName, class: el.className, z: z};
    }
  });
  return {overlay, maxZ};
}

() => {
  const link = document.querySelector('a[aria-label="Park Rite Parking"]');
  if (link) {
    link.scrollIntoView({behavior: 'instant', block: 'center'});
    link.click();
    return {clicked: true};
  }
  return {clicked: false};
}

() => {
  // Try to remove any overlay
  const overlays = document.querySelectorAll('div[aria-hidden="true"], div[role="presentation"]');
  let result = {found: overlays.length};
  overlays.forEach(el => {
    el.style.display = 'none';
  });

  // Also try clicking on map canvas
  const canvas = document.querySelector('canvas');
  if (canvas) {
    canvas.click();
    result.canvasClicked = true;
  }
  return result;
}

() => {
  const closeBtns = document.querySelectorAll('button[aria-label="关闭"]');
  let result = [];
  closeBtns.forEach((btn, i) => {
    const rect = btn.getBoundingClientRect();
    result.push({i, top: rect.top, left: rect.left, visible: rect.width > 0 && rect.height > 0});
  });
  return result;
}

() => {
  const searchBox = document.querySelector('input[name="q"]');
  if (searchBox) {
    searchBox.value = '';
    searchBox.focus();
    return {found: true};
  }
  return {found: false};
}

() => {
  // Find any modal/overlay elements
  const overlays = document.querySelectorAll('[role="dialog"], [aria-modal="true"], .modal, .overlay, [data-modal], [class*="modal"], [class*="overlay"]');
  let removed = [];
  overlays.forEach(el => {
    if (el.offsetParent !== null || el.getBoundingClientRect().width > 0) {
      const rect = el.getBoundingClientRect();
      removed.push({tag: el.tagName, class: el.className, id: el.id, w: rect.width, h: rect.height});
      el.remove();
    }
  });

  // Find any visible element with high z-index
  const allEls = document.querySelectorAll('*');
  allEls.forEach(el => {
    const style = window.getComputedStyle(el);
    if (style.position === 'fixed' && parseInt(style.zIndex) > 100 && el.offsetParent !== null) {
      const rect = el.getBoundingClientRect();
      if (rect.width > 200) {
        removed.push({tag: el.tagName, class: el.className, w: rect.width, h: rect.height, z: style.zIndex});
        el.style.display = 'none';
      }
    }
  });

  return {removed: removed.length, details: removed.slice(0, 10)};
}
